<template><div class="min-h-screen grid lg:grid-cols-2"><section class="hidden lg:flex bg-brand-900 text-white p-14 flex-col justify-between"><div class="text-2xl font-bold">JotnoHealthcare</div><div><h1 class="text-5xl font-bold leading-tight">Healthcare,<br>when you need it.</h1><p class="text-teal-100 mt-5 max-w-md">A connected virtual care prototype for patients and care teams.</p></div><p class="text-xs text-teal-100">Academic demonstration only · Not for real clinical use</p></section><section class="grid place-items-center p-6"><form class="panel p-8 w-full max-w-md" @submit.prevent="login"><router-link to="/" class="text-brand-700 text-sm">← Back to home</router-link><h2 class="text-3xl font-bold mt-6">Welcome back</h2><p class="muted mt-2">Sign in to your workspace</p><label class="block text-sm font-semibold mt-7">Email</label><input v-model="email" type="email" class="field mt-2" required><label class="block text-sm font-semibold mt-4">Password</label><input v-model="password" type="password" class="field mt-2" required><p v-if="error" class="text-red-600 text-sm mt-3">{{error}}</p><button class="btn w-full mt-6" :disabled="busy">{{busy?'Signing in…':'Sign in'}}</button><p class="text-xs muted mt-5">Demo accounts: admin@jotno.test, doctor@jotno.test, specialist@jotno.test, patient@jotno.test, caregiver@jotno.test · password: password</p></form></section></div></template><script setup>import{ref}from'vue';import{useRouter}from'vue-router';import api from'../services/api';const router=useRouter(),email=ref('patient@jotno.test'),password=ref('password'),error=ref(''),busy=ref(false);async function login(){busy.value=true;error.value='';try{const{data}=await api.post('/login',{email:email.value,password:password.value});localStorage.setItem('jh_token',data.token);localStorage.setItem('jh_user',JSON.stringify(data.user));router.push('/dashboard')}catch(e){error.value=e.response?.data?.message||'Could not connect to the API. Check that Laravel is running.'}finally{busy.value=false}}</script>
